import csv, json, os
base='/root/data/indiv-stock'
last_close={}
for fname in sorted(os.listdir(base)):
    if not fname.endswith('.csv'):
        continue
    ticker=fname[:-4]
    path=os.path.join(base,fname)
    last=None
    with open(path, newline='') as f:
        reader=csv.DictReader(f)
        for row in reader:
            if row.get('Close'):
                last=row
    if last and last.get('Close'):
        try:
            last_close[ticker]=float(last['Close'])
        except ValueError:
            pass
print(json.dumps(last_close, sort_keys=True))
