/* global d3 */
(function () {
  const width = 720;
  const height = 520;

  const svg = d3
    .select("#bubble-chart")
    .attr("viewBox", `0 0 ${width} ${height}`)
    .attr("preserveAspectRatio", "xMidYMid meet");

  const tooltip = d3.select("#tooltip");

  const lastCloseMap = {
    "AAPL": 43.66749954223633,
    "AMD": 11.260000228881836,
    "AMZN": 1125.3499755859375,
    "BA": 260.8500061035156,
    "BAC": 26.51000022888184,
    "BLK": 465.8299865722656,
    "C": 72.25,
    "CLR": 46.68999862670898,
    "CSCO": 33.9900016784668,
    "CSL": 109.06999969482422,
    "DVN": 40.40999984741211,
    "EOG": 104.58000183105467,
    "FB": 178.4600067138672,
    "FDX": 218.1499938964844,
    "GE": 157.61538696289062,
    "HFC": 42.04999923706055,
    "HON": 139.69398498535156,
    "INTC": 45.58000183105469,
    "JPM": 97.51000213623048,
    "MA": 149.5399932861328,
    "MET": 52.20000076293945,
    "MMM": 227.4499969482422,
    "MPC": 61.720001220703125,
    "MRO": 15.619999885559082,
    "MSFT": 83.87000274658203,
    "NEE": 38.790000915527344,
    "NFLX": 192.0200042724609,
    "NLSN": 36.619998931884766,
    "NVDA": 54.03499984741211,
    "PXD": 158.92999267578125,
    "RHI": 52.900001525878906,
    "RY": 78.73999786376953,
    "SCHW": 44.27000045776367,
    "TRGP": 44.130001068115234,
    "TSLA": 60.59799957275391,
    "TSM": 41.720001220703125,
    "UPS": 113.2300033569336,
    "V": 111.87999725341795,
    "WFC": 53.810001373291016,
    "XOM": 82.94000244140625,
    "gld": 121.13,
    "qqq": 153.68,
    "spy": 258.09,
    "vea": 44.04,
    "voo": 237.04,
    "vtv": 101.56,
    "vwo": 44.59,
    "xlf": 26.08,
    "xlu": 55.51,
    "xlv": 81.2
  };

  const formatMarketCap = (value) => {
    if (!value || !Number.isFinite(value)) {
      return "—";
    }
    const absValue = Math.abs(value);
    if (absValue >= 1e12) {
      return `${trimZeros((value / 1e12).toFixed(2))}T`;
    }
    if (absValue >= 1e9) {
      return `${trimZeros((value / 1e9).toFixed(2))}B`;
    }
    if (absValue >= 1e6) {
      return `${trimZeros((value / 1e6).toFixed(2))}M`;
    }
    if (absValue >= 1e3) {
      return `${trimZeros((value / 1e3).toFixed(2))}K`;
    }
    return trimZeros(value.toFixed(2));
  };

  const trimZeros = (value) => value.replace(/\.00$/, "").replace(/(\.\d)0$/, "$1");
  const formatPrice = d3.format("$,.2f");

  d3.csv("data/stock-descriptions.csv", (d) => {
    const marketCapValue = d.marketCap ? +d.marketCap : NaN;
    const marketCap = Number.isFinite(marketCapValue) ? marketCapValue : null;
    const ticker = (d.ticker || "").trim();
    const fallbackKey = ticker.toLowerCase();
    const lastClose = lastCloseMap[ticker] ?? lastCloseMap[fallbackKey] ?? null;

    return {
      ticker,
      sector: (d.sector || "").trim(),
      name: (d["full name"] || "").trim(),
      marketCap,
      country: (d.country || "").trim(),
      website: (d.website || "").trim(),
      lastClose,
      hasDetails: Boolean(marketCap && d.country && d.website)
    };
  }).then((data) => {
    data.sort((a, b) => {
      const sectorOrder = d3.ascending(a.sector, b.sector);
      if (sectorOrder !== 0) return sectorOrder;
      return d3.ascending(a.ticker, b.ticker);
    });

    const sectors = Array.from(new Set(data.map((d) => d.sector))).sort(d3.ascending);

    const palette = [
      "#1b4965",
      "#5fa8d3",
      "#f4b942",
      "#9b4dca",
      "#f07167",
      "#5b8e7d",
      "#2a9d8f",
      "#e76f51",
      "#5d3a00",
      "#577590"
    ];

    const colorScale = d3.scaleOrdinal().domain(sectors).range(palette.slice(0, sectors.length));

    const clusterPositions = {};
    const cols = Math.ceil(Math.sqrt(sectors.length));
    const rows = Math.ceil(sectors.length / cols);
    const xSpacing = width / (cols + 1);
    const ySpacing = height / (rows + 1);

    sectors.forEach((sector, i) => {
      const col = i % cols;
      const row = Math.floor(i / cols);
      clusterPositions[sector] = {
        x: xSpacing * (col + 1),
        y: ySpacing * (row + 1)
      };
    });

    const marketCaps = data.map((d) => d.marketCap).filter((d) => d && Number.isFinite(d));
    const minCap = d3.min(marketCaps);
    const maxCap = d3.max(marketCaps);
    const radiusScale = d3
      .scaleSqrt()
      .domain([minCap || 0, maxCap || 1])
      .range([14, 48]);

    const sectorCounts = {};
    data.forEach((d) => {
      const cluster = clusterPositions[d.sector];
      const index = sectorCounts[d.sector] || 0;
      sectorCounts[d.sector] = index + 1;
      const col = index % 5;
      const row = Math.floor(index / 5);
      const offsetX = (col - 2) * 10;
      const offsetY = (row - 2) * 10;
      d.r = d.marketCap ? radiusScale(d.marketCap) : 12;
      d.x = cluster.x + offsetX;
      d.y = cluster.y + offsetY;
    });

    const simulation = d3
      .forceSimulation(data)
      .force("x", d3.forceX((d) => clusterPositions[d.sector].x).strength(0.15))
      .force("y", d3.forceY((d) => clusterPositions[d.sector].y).strength(0.15))
      .force("collide", d3.forceCollide((d) => d.r + 1).iterations(2))
      .stop();

    for (let i = 0; i < 320; i += 1) {
      simulation.tick();
    }

    const nodes = svg
      .append("g")
      .attr("class", "nodes")
      .selectAll("g")
      .data(data, (d) => d.ticker)
      .join("g")
      .attr("class", "node")
      .attr("transform", (d) => `translate(${d.x},${d.y})`)
      .style("cursor", (d) => (d.hasDetails ? "pointer" : "default"));

    nodes
      .append("circle")
      .attr("r", (d) => d.r)
      .attr("fill", (d) => colorScale(d.sector))
      .attr("fill-opacity", 0.85);

    nodes
      .append("text")
      .text((d) => d.ticker)
      .attr("text-anchor", "middle")
      .attr("dy", "0.35em")
      .style("font-size", (d) => `${Math.min(14, Math.max(8, d.r / 2.2))}px`);

    const legend = d3.select("#legend");
    const legendItems = legend.selectAll("div").data(sectors, (d) => d);

    const legendEnter = legendItems
      .enter()
      .append("div")
      .attr("class", "legend-item");

    legendEnter
      .append("span")
      .attr("class", "legend-swatch")
      .style("background", (d) => colorScale(d));

    legendEnter.append("span").text((d) => d);

    const tableBody = d3.select("#stock-table tbody");
    const rowsSelection = tableBody
      .selectAll("tr")
      .data(data, (d) => d.ticker)
      .join("tr")
      .attr("data-ticker", (d) => d.ticker);

    rowsSelection.append("td").text((d) => d.ticker);
    rowsSelection.append("td").text((d) => d.name || "—");
    rowsSelection.append("td").text((d) => d.sector || "—");
    rowsSelection.append("td").text((d) => formatMarketCap(d.marketCap));

    let selectedTicker = null;

    const setSelected = (ticker) => {
      if (ticker && ticker === selectedTicker) {
        selectedTicker = null;
      } else {
        selectedTicker = ticker;
      }

      nodes.classed("selected", (d) => d.ticker === selectedTicker);
      rowsSelection.classed("selected", (d) => d.ticker === selectedTicker);
    };

    const showTooltip = (event, d) => {
      if (!d.hasDetails) {
        return;
      }
      const latestClose = d.lastClose ? `<div><span class="label">Latest close:</span> ${formatPrice(d.lastClose)}</div>` : "";
      tooltip
        .html(
          `<div><span class="label">${d.ticker}</span></div>` +
            `<div>${d.name}</div>` +
            `<div><span class="label">Sector:</span> ${d.sector}</div>` +
            latestClose
        )
        .style("left", `${event.pageX + 12}px`)
        .style("top", `${event.pageY - 28}px`)
        .classed("visible", true);
    };

    const moveTooltip = (event, d) => {
      if (!d.hasDetails) {
        return;
      }
      tooltip
        .style("left", `${event.pageX + 12}px`)
        .style("top", `${event.pageY - 28}px`);
    };

    const hideTooltip = (d) => {
      if (!d.hasDetails) {
        return;
      }
      tooltip.classed("visible", false);
    };

    nodes
      .on("mouseover", function (event, d) {
        showTooltip(event, d);
      })
      .on("mousemove", function (event, d) {
        moveTooltip(event, d);
      })
      .on("mouseout", function (event, d) {
        hideTooltip(d);
      })
      .on("click", function (event, d) {
        event.stopPropagation();
        setSelected(d.ticker);
      });

    rowsSelection.on("click", function (event, d) {
      event.stopPropagation();
      setSelected(d.ticker);
    });

    d3.select(document.body).on("click", function () {
      setSelected(null);
    });
  });
})();
JS"}
